var opponentDetailIdentity=null,opponentDetailComparison=null,opponentDetailOpener=null,opponentDetailStamp='';
function opponentDetailHTML(d){
 const p=d.person,esc=matchdayText,round=n=>Math.round(n),energy=round(p.energy),energyTier=energy<35?'low':energy<65?'mid':'high';
 return '<div class="opponent-detail-content"><header class="opponent-detail-top"><span>상대 선수 보고서 · '+d.minute+'분</span><button type="button" id="opponent-detail-close" aria-label="상대 선수 상세 닫기">닫기</button></header><div class="opponent-detail-hero">'+Portraits.html(p,{size:'large'})+'<div><small>'+esc(d.club.name)+' · #'+p.no+' · '+esc({GK:'골키퍼',DEF:'수비수',MID:'미드필더',FW:'공격수'}[p.pos])+'</small><h2 id="opponent-detail-name">'+esc(p.name)+'</h2><p>'+(p.dismissed?'퇴장 · '+d.cards.red.minute+'분':p.replacementFor?'후보 출전 · '+esc(p.replacementFor)+'의 대체 선수':d.featured?'코치가 주목한 요주의 선수':'이번 경기 '+(d.phase==='prep'?'예상 선발':'출전 명단'))+'</p></div></div><div class="opponent-detail-summary"><div><span>종합 · 계산</span><strong>'+p.overall+'</strong></div><div class="opponent-detail-energy"><span>현재 체력</span><div class="opponent-energy-gauge '+energyTier+'" role="meter" aria-label="'+esc(p.name)+' 체력" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+energy+'"><i style="height:'+energy+'%"></i></div><strong>'+energy+'</strong><small>'+esc(p.condition)+(d.cards.yellow?' · 경고 '+d.cards.yellow:'')+'</small></div><div><span>높은 기본 능력</span>'+d.strengths.map(r=>'<b>'+r.label+' '+r.value+'</b>').join('')+'</div></div><section class="opponent-role-report" aria-label="상대의 역할 지표"><h3>이 선수의 활용 유형</h3><div>'+d.roles.map(r=>'<article><span>'+r.label+'</span><strong>'+r.score+'</strong><small>'+r.basis+'</small></article>').join('')+'</div></section><section class="opponent-detail-compare"><h3>우리 선수와 능력 비교</h3>'+(d.choices.length?'<label for="opponent-detail-comparison">비교할 우리 선수<select id="opponent-detail-comparison">'+d.choices.map(row=>'<option value="'+esc(row.identity)+'"'+(row.identity===d.comparison.identity?' selected':'')+'>'+esc(row.name)+' · '+esc(row.pos)+'</option>').join('')+'</select></label><div class="opponent-comparison-person">'+Portraits.html(d.comparison)+'<span><b>'+esc(d.comparison.name)+'</b><small>현재 활동 선수 · 종합 '+d.comparison.overall+' · 체력 '+round(d.comparison.energy)+'</small></span></div>':'<p>현재 비교할 활동 선수가 없습니다.</p>')+'<table aria-label="상대와 우리 선수 기본 능력 비교"><thead><tr><th>능력</th><th>상대</th><th>우리</th><th>차이</th></tr></thead><tbody>'+d.rows.map(r=>'<tr'+(r.primary?' class="opponent-primary-stat"':'')+'><th scope="row">'+r.label+(r.primary?'<small>주요 능력</small>':'')+'</th><td><b>'+r.value+'</b></td><td>'+(r.ours??'—')+'</td><td class="'+(r.delta>0?'gain':r.delta<0?'loss':'')+'">'+(r.delta===null?'—':r.delta>0?'+'+r.delta:r.delta)+'</td></tr>').join('')+'</tbody></table><p>차이는 우리 선수 − 상대 선수입니다. 기본 능력을 비교하므로 배치·남은 체력·전술도 함께 판단하세요.</p></section><details class="opponent-detail-source"><summary>보고서 기준</summary><p id="opponent-detail-description">'+esc(d.note)+'</p><p>구단과 이름은 실제 축구에서 착안한 가상 설정이며 얼굴은 창작 일러스트입니다. '+(p.replacementFor?'대체 선수의 낮아진 실제 게임 능력을 표시합니다.':'')+'</p></details><footer><button type="button" id="opponent-detail-prev">이전 선수</button><span>'+p.no+' / 11</span><button type="button" id="opponent-detail-next">다음 선수</button></footer></div>';
}
function renderOpponentDetails(model){
 const dialog=$('opponent-detail-dialog');if(!dialog?.open&&!model)return;const d=model||OpponentDetails.read(season,opponentDetailIdentity,opponentDetailComparison);if(!d.valid){closeOpponentDetails();return;}const stamp=JSON.stringify(d);if(stamp===opponentDetailStamp)return;
 const scroll=dialog.scrollTop,focus=dialog.contains(document.activeElement)?document.activeElement.id:null;dialog.innerHTML=opponentDetailHTML(d);opponentDetailStamp=stamp;dialog.scrollTop=scroll;
 $('opponent-detail-close').onclick=closeOpponentDetails;const compare=$('opponent-detail-comparison');if(compare)compare.onchange=()=>{opponentDetailComparison=compare.value;renderOpponentDetails();};
 for(const [id,step] of [['opponent-detail-prev',-1],['opponent-detail-next',1]])$(id).onclick=()=>{const lineup=Opposition.read(season).lineup,index=lineup.findIndex(p=>p.identity===opponentDetailIdentity);if(index<0)return closeOpponentDetails();openOpponentDetails(lineup[(index+step+lineup.length)%lineup.length].identity);dialog.scrollTop=0;$('opponent-detail-close').focus({preventScroll:true});};
 if(focus)$(focus)?.focus({preventScroll:true});
}
function openOpponentDetails(identity,opener){
 const d=OpponentDetails.read(season,identity);if(!d.valid||view!=='match'||typeof practiceSession!=='undefined'&&practiceSession)return;const dialog=$('opponent-detail-dialog'),open=dialog.open;
 if(!open){opponentDetailOpener=opener||document.activeElement;if(typeof pauseForPlanning==='function')pauseForPlanning();}
 if(opponentDetailIdentity!==identity){opponentDetailComparison=null;opponentDetailStamp='';}opponentDetailIdentity=identity;renderOpponentDetails(d);
 if(!open){dialog.scrollTop=0;dialog.showModal();document.documentElement.classList.add('opponent-detail-open');$('opponent-detail-close').focus({preventScroll:true});}
}
function closeOpponentDetails(){
 const dialog=$('opponent-detail-dialog'),identity=opponentDetailIdentity,opener=opponentDetailOpener;opponentDetailIdentity=null;opponentDetailComparison=null;opponentDetailOpener=null;opponentDetailStamp='';if(dialog.open)dialog.close();document.documentElement.classList.remove('opponent-detail-open');
 const visible=e=>e?.isConnected&&e.getClientRects().length,replace=[...document.querySelectorAll('[data-opponent-player]')].find(e=>e.dataset.opponentPlayer===identity&&visible(e));(visible(opener)?opener:replace)?.focus({preventScroll:true});
}
const opponentDetailDialog=document.createElement('dialog');opponentDetailDialog.id='opponent-detail-dialog';opponentDetailDialog.setAttribute('aria-labelledby','opponent-detail-name');opponentDetailDialog.setAttribute('aria-modal','true');document.body.append(opponentDetailDialog);
document.addEventListener('click',e=>{const button=e.target.closest('[data-opponent-player]');if(button)openOpponentDetails(button.dataset.opponentPlayer,button);});
opponentDetailDialog.addEventListener('cancel',e=>{e.preventDefault();closeOpponentDetails();});
opponentDetailDialog.addEventListener('close',()=>{document.documentElement.classList.remove('opponent-detail-open');});
opponentDetailDialog.addEventListener('click',e=>{if(e.target!==opponentDetailDialog)return;const r=opponentDetailDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeOpponentDetails();});
